#!/bin/sh
# Generated by forge. Answers a permission ask when nobody can: in an autonomous
# run (claude -p, the Agent SDK, CI), an ask is otherwise denied without anyone
# looking at it. A separate, context-free Claude session reviews the action alone
# (no conversation, read-only tools, no hooks) and allows or denies it.
#   PermissionRequest hook:  sh review.sh            (hook input on stdin)
#   from guard.sh:           sh review.sh pre <rule> (a guard ask; input on stdin)
# Prints nothing (the usual dialog, or the usual denial) when a human can answer,
# when FORGE_ASK_REVIEW=never, in dontAsk mode, or when claude cannot run.
dir=$(cd "$(dirname "$0")" && pwd)
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
event=${1:-permission}
why=${2:-}

forge_review_wanted || exit 0
# the project-level copy defers to the user-level one, so an ask is reviewed once
if [ "$event" = permission ] && [ "$(basename "$(dirname "$dir")")" = forge-project ] \
  && [ -f "$HOME/.claude/skills/forge-user/scripts/review.sh" ]; then exit 0; fi

tool=$(json_get tool_name)
input=$(printf '%s' "$FORGE_INPUT" | forge_json_object tool_input)
verdict=$(forge_review "$tool" "$input" "$why") || exit 0
decision=${verdict%%"	"*}
reason=$(printf '%s' "${verdict#*"	"}" | json_escape)
forge_review_log "$decision" "$tool" "$input" "${verdict#*"	"}"
if [ "$event" = pre ]; then
  printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"%s","permissionDecisionReason":"forge:%s reviewed by an independent session, nobody being there to answer: %s"}}\n' "$decision" "$why" "$reason"
elif [ "$decision" = allow ]; then
  printf '{"hookSpecificOutput":{"hookEventName":"PermissionRequest","decision":{"behavior":"allow"}}}\n'
else
  printf '{"hookSpecificOutput":{"hookEventName":"PermissionRequest","decision":{"behavior":"deny","message":"forge: denied by an independent review, nobody being there to answer: %s"}}}\n' "$reason"
fi
exit 0
